// And groups predicates with the AND operator between them.
func And(predicates ...predicate.BundleRollouts) predicate.BundleRollouts {
	return predicate.BundleRollouts(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.BundleRollouts) predicate.BundleRollouts {
	return predicate.BundleRollouts(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.BundleRollouts) predicate.BundleRollouts {
	return predicate.BundleRollouts(sql.NotPredicates(p))
}
